#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;

    regex pattern("\\([a-zA-Z_]*\\)");
    string newString = regex_replace(s, pattern, "_");

    vector<string> left;
    size_t pos = 0;
    while ((pos = newString.find('_')) != string::npos) {
        left.push_back(newString.substr(0, pos));
        newString.erase(0, pos + 1);
    }
    left.push_back(newString);

    int maxLength = 0;
    for (const auto& part : left) {
        maxLength = max(maxLength, (int)part.length());
    }
    cout << maxLength << "\n";

    int count = 0;
    bool isStart = false;
    int startIndex = -1, endIndex = -1;
    for (int i = 0; i < (int)s.size(); ++i) {
        char c = s[i];
        if (c == '(') {
            isStart = true;
            startIndex = i;
            continue;
        }
        if (isStart) {
            if (c == ')') {
                isStart = false;
                endIndex = i;
                string tmp = s.substr(startIndex + 1, endIndex - startIndex - 1);
                if (tmp == "")
                    continue;
                if (tmp[0] == '_') {
                    vector<string> tmps;
                    size_t pos2 = 0;
                    while ((pos2 = tmp.find('_')) != string::npos) {
                        tmps.push_back(tmp.substr(0, pos2));
                        tmp.erase(0, pos2 + 1);
                    }
                    tmps.push_back(tmp);
                    if (!tmps.empty())
                        count += (int)tmps.size() - 1;
                } else {
                    vector<string> tmps;
                    size_t pos2 = 0;
                    string tmp2 = tmp;
                    while ((pos2 = tmp2.find('_')) != string::npos) {
                        tmps.push_back(tmp2.substr(0, pos2));
                        tmp2.erase(0, pos2 + 1);
                    }
                    tmps.push_back(tmp2);
                    count += (int)tmps.size();
                }
            }
        }
    }
    cout << count << "\n";

    return 0;
}
